import{_ as s,C as o,o as n,c as r,j as t,a as i,E as h,a6 as l}from"./chunks/framework.CCKCzdWs.js";const k=JSON.parse(`{"title":"Inspect a running test's page","description":"In the live view of a running Playwright test, Inspect shows the page at each call as a document, before it, at its action and after it, with the locator picker; sent only while open, and never stored.","frontmatter":{"title":"Inspect a running test's page","description":"In the live view of a running Playwright test, Inspect shows the page at each call as a document, before it, at its action and after it, with the locator picker; sent only while open, and never stored.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/live-inspect.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/live-inspect.html"}],["meta",{"property":"og:title","content":"Inspect a running test's page | Piwi for Playwright"}],["meta",{"property":"og:description","content":"In the live view of a running Playwright test, Inspect shows the page at each call as a document, before it, at its action and after it, with the locator picker; sent only while open, and never stored."}]]},"headers":[],"relativePath":"features/live-inspect.md","filePath":"features/live-inspect.md","lastUpdated":1794647275000}`),d={name:"features/live-inspect.md"};function c(p,e,g,w,m,f){const a=o("Needs");return n(),r("div",null,[e[0]||(e[0]=t("h1",{id:"inspect-a-running-test-s-page",tabindex:"-1"},[i("Inspect a running test's page "),t("a",{class:"header-anchor",href:"#inspect-a-running-test-s-page","aria-label":`Permalink to "Inspect a running test's page"`},"​")],-1)),h(a,{reporter:"",fixtures:""}),e[1]||(e[1]=l('<p>Under a worker&#39;s <a href="./live-view.html">live view</a>, <strong>Inspect</strong> shows its test&#39;s page as a document rather than an image: the DOM Playwright&#39;s trace takes at each call (before the call, at its action and after it), rendered by the dashboard with its stylesheets and images, and the locator picker on it. It is for a CI test that waits on an element: you see the page as the test sees it, at the call it is stuck on, and pick the locator to use while the test still waits. It works in a CI run or a run <a href="./share-live.html">shared from a developer&#39;s machine</a>, and the dashboard stores none of it. The <a href="./desktop-runs.html#watch">desktop app</a> shows the same view of its own runs, from the test&#39;s own trace.</p><h2 id="use-it" tabindex="-1">Use it <a class="header-anchor" href="#use-it" aria-label="Permalink to &quot;Use it&quot;">​</a></h2><p>In the lane panel of a running test, open <strong>Inspect</strong> under the image.</p><ul><li><strong>The latest call.</strong> The view opens on the page at the latest call the worker sent, and shows each new call as it comes while <strong>Follow the latest call</strong> is on: about three a second at most while they keep coming, the latest each time.</li><li><strong>Before, Action, After.</strong> The page before the call ran, at its action (where a click or a fill acts, for an input action) and after it. A moment the worker sent no page of stays greyed out.</li><li><strong>The calls.</strong> Under the page, each call whose page came, the latest last. Choosing an older one turns following off, so the view stays on it as the test goes on; tick <strong>Follow the latest call</strong> to go back to the newest.</li><li><strong>Pick a locator</strong> opens the <a href="./evidence.html#one-execution-diagnosis-first">snapshot picker</a> on the page shown: click an element to get the locators that target it, ranked, to copy. Picking turns following off. Nothing is saved: the test is still running.</li></ul><p>As the test ends, the dashboard lets its pages go: the page shown stays, but no other call&#39;s page opens and Pick a locator is off. The view goes on with the lane&#39;s next test, as the image does, following its latest call. When no page comes, Inspect says why, in place of the page or above the calls it already lists.</p><h2 id="where-the-pages-come-from" tabindex="-1">Where the pages come from <a class="header-anchor" href="#where-the-pages-come-from" aria-label="Permalink to &quot;Where the pages come from&quot;">​</a></h2><ul><li><strong>The test&#39;s own trace</strong>, when the project&#39;s <code>trace</code> option records this attempt: the worker reads the snapshots the trace takes as it grows. Nothing in the trace changes, and the archive the runner keeps is the same.</li><li><strong>Otherwise, a trace of the worker&#39;s own</strong>, started when the first viewer opens Inspect, taking DOM snapshots alone, and stopped unsaved when the last closes it: its files are deleted, and so are the response bodies it wrote to the trace folder&#39;s <code>resources/</code> that no other trace there names, then or as the test&#39;s context closes. A test that starts or stops tracing itself meanwhile, even while the worker&#39;s trace starts or stops, waits for the worker&#39;s trace to stop, then goes; the worker starts none again until the test&#39;s own stops. That trace sees only what the page loads from then on, so a page loaded before Inspect opened may show unstyled until the test loads it again. Playwright&#39;s snapshot script stays in the pages that context opens later.</li></ul><h2 id="what-is-sent-and-what-is-not" tabindex="-1">What is sent, and what is not <a class="header-anchor" href="#what-is-sent-and-what-is-not" aria-label="Permalink to &quot;What is sent, and what is not&quot;">​</a></h2><ul><li><strong>Nothing until someone opens Inspect.</strong> The worker sends pages only while a viewer of it has Inspect open: first the page&#39;s snapshots since its last navigation, 16 MB at most, then each new one, 12 a second at most. Past 16 MB, the oldest snapshots after a frame&#39;s full one are left out, never the full one, which the others build on; a large trace starts from the page&#39;s last navigation. A snapshot is 4 MB at most. Each waits once, a second at most, behind the view&#39;s images, then goes, and its bytes space the images after it: the image can slow while Inspect sends.</li><li><strong>The stylesheets, fonts and images a page names</strong>, once per run, 2 MB each at most, each sent only when its bytes are of the kind its type says; fonts are WOFF, WOFF2, TTF, OTF, font collections and EOT alone. Never a script, a document, an SVG or an SVG font.</li><li><strong>Secrets.</strong> Before a page leaves the worker, the value of each field that holds a secret is removed: a password, a one-time code, a card&#39;s number or code, a field whose name, label (an <code>aria-labelledby</code> one too) or <code>autocomplete</code> names one. So is any text equal to a value the test&#39;s secret fields held or its calls typed into one, and anything that reads as a card&#39;s number: each reads <code>&lt;hidden&gt;</code>. Each address in the page (its links, sources, forms, its own and its stylesheets&#39;) and each text and attribute value has its credentials hidden, as the <a href="./live-view-layers.html#page-events">page&#39;s events</a> do: a URL&#39;s password, a query value named or shaped like a token, a key&#39;s or a JWT&#39;s shape anywhere. A <code>meta</code> named for a token, a key or a secret has its content hidden. The dashboard hides fields, credentials and those <code>meta</code> again before it renders a page: a secret field shows empty.</li><li><strong>No page the worker could not clean</strong>: one whose secret fields it could not read, or whose snapshot it could not read whole (deeper than 512 levels, more than 500,000 nodes, or naming one it no longer holds).</li><li><strong>A project with Masked elements gets no page.</strong> Its masks are locators, which a snapshot cannot apply. As a project starts masking elements, the dashboard lets go of every page it kept of its live runs and takes no more.</li><li><strong>No script of the page runs.</strong> The worker empties a script Playwright kept (an SVG&#39;s) and leaves out an attribute whose address runs one. The dashboard renders each page itself, its scripts, inline handlers and <code>javascript:</code> links left out, in a sandboxed frame that loads nothing from the network.</li></ul><h2 id="what-the-dashboard-keeps" tabindex="-1">What the dashboard keeps <a class="header-anchor" href="#what-the-dashboard-keeps" aria-label="Permalink to &quot;What the dashboard keeps&quot;">​</a></h2><p>The pages and their resources stay in the dashboard server&#39;s memory, for the run alone, and only those of each worker&#39;s running test: a worker&#39;s pages go as its test ends. It keeps each worker&#39;s latest 32 MB of pages (8,192 at most), 128 MB for the run&#39;s workers together (32,768), the resources they name, the 64 MB used last (4,096), and the 8 rendered pages read last, until one they are built from goes. Every live run&#39;s together take 512 MB at most: past it, no new page is kept until runs end. Nothing goes to the database, the disk, the logs or an export, and it all goes when the run ends.</p><p>Who sees them: who may open the run, each from their own view, as for the <a href="./live-view.html#what-is-sent-to-whom-and-what-is-kept">images</a>. The dashboard takes pages only from a worker someone inspects: 24 a second from each worker, 8 MB of resources a second, and 16 MB of pages and resources a second from the run&#39;s workers together, apart from their images.</p><h2 id="when-no-page-comes" tabindex="-1">When no page comes <a class="header-anchor" href="#when-no-page-comes" aria-label="Permalink to &quot;When no page comes&quot;">​</a></h2><p>Inspect says why:</p><ul><li><strong>The project masks elements.</strong> When the worker&#39;s reporter cannot read the masks, Inspect asks to update it.</li><li><strong>The trace takes no DOM snapshots</strong> (<code>snapshots</code> off, or in Playwright 1.64 an object without <code>dom</code>), the browser keeps no trace folder, or the test traces itself: open Inspect again once its trace stopped.</li><li><strong>A page not sent</strong>: its secret fields or its snapshot could not be read, it passes 4 MB, Inspect fell behind the test&#39;s calls (16 MB waiting), or the page&#39;s full snapshots alone pass 16 MB. Most say Inspect sends it again from its next navigation.</li><li><strong>A page no longer kept</strong>: let go at the bounds above, of a test that ended, or as the project began masking elements; built on a page the worker did not send; or one the dashboard cannot read whole or render in time.</li><li><strong>The view ended</strong>: the run ended, the live view was turned off, the test ended, or the view closed.</li></ul><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>The test&#39;s <code>page</code>, its main frame.</strong> An iframe&#39;s content is not shown, nor another page of the test.</li><li><strong>A worker of an older reporter</strong> sends no page: Inspect waits for one.</li><li><strong>A trace&#39;s snapshots, not the live page.</strong> A page shows what Playwright recorded at a call: an element that appears between two calls shows at the next.</li></ul><h2 id="in-the-demo" tabindex="-1">In the demo <a class="header-anchor" href="#in-the-demo" aria-label="Permalink to &quot;In the demo&quot;">​</a></h2><p>The live demo runs no browser, and Inspect needs a running test: <a href="./watch-all.html#in-the-demo">Watch all</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./live-view.html">Live view of a run</a>: turning it on, and the image and call of one worker</li><li><a href="./live-view-layers.html">Page events, text and filmstrip</a>: what the page and its requests said, beside the image</li><li><a href="./evidence.html">Failure evidence</a>: the DOM snapshot and the picker of a finished test</li><li><a href="./share-live.html">Share a run live</a>: a run on your machine, watched from the dashboard</li></ul>',21))])}const v=s(d,[["render",c]]);export{k as __pageData,v as default};
